<?php
declare(strict_types=1);
header("Content-Security-Policy: default-src 'self'; img-src 'self' data:; style-src 'self'; script-src 'none'; frame-ancestors 'self'; form-action 'self'; base-uri 'none'");
$section=trim(substr($path,6),'/')?:'dashboard';
$sections=['dashboard'=>'Overview','enquiries'=>'Enquiries','pages'=>'Website pages','products'=>'Products','certificates'=>'Certificates','media'=>'Media library','company'=>'Company details','users'=>'Administrators','account'=>'My account'];
$error='';$current=user();
if($section==='login' && $current)redirect('/admin');
if(!$current && $section!=='login')redirect('/admin/login');
if($_SERVER['REQUEST_METHOD']==='POST'){
 try{
  checkCsrf();$action=(string)($_POST['action']??'');
  if($section==='login'){
   throttle('login:'.($_SERVER['REMOTE_ADDR']??''),12,900);
   $mail=email(required('email',190));throttle('account:'.$mail,8,900);
   $u=query('SELECT * FROM users WHERE email=? AND active=1',[$mail])->fetch();
   $hash=$u['password']??'$2y$10$92IXUNpkjO0rOQ5byMi.Ye4oKoEa3Ro9llC/.og/at2uheWG/igi.';
   if(!password_verify((string)($_POST['password']??''),$hash)||!$u)throw new InvalidArgumentException('Email or password is incorrect.');
   session_regenerate_id(true);$_SESSION=['user_id'=>$u['id'],'auth_hash'=>$u['password'],'last_seen'=>time(),'csrf'=>bin2hex(random_bytes(32))];audit('Signed in');redirect('/admin');
  }
  if(!$current)redirect('/admin/login');
  if($action==='logout'){$_SESSION=[];session_destroy();redirect('/admin/login');}
  if($section==='company'){
   $data=[];foreach(['name','email','phone','gst','established','partners','address','branch','site','experience','capacity','video'] as $key)$data[$key]=required($key,in_array($key,['address','branch','site'])?2000:190);
   $data['email']=email($data['email']);
   if(!preg_match('/^[A-Za-z0-9_-]{11}$/',$data['video']))throw new InvalidArgumentException('Use the 11-character YouTube video ID.');
   if(!ctype_digit($data['capacity'])||(int)$data['capacity']<1)throw new InvalidArgumentException('Capacity must be a positive number in TPH.');
   $data['logo']=(string)($_POST['logo']??'');imageUrl($data['logo']);save('company','settings',$data);
  }elseif($section==='pages'){
   $slug=required('slug');$doc=document($slug);$nodes=textNodes($doc);$data=['text'=>[],'images'=>[],'alts'=>[],'title'=>mb_substr((string)($_POST['seo_title']??''),0,200),'description'=>mb_substr((string)($_POST['seo_description']??''),0,500)];
   foreach($nodes as $i=>$n){$value=(string)($_POST['text'][$i]??$n->nodeValue);if(mb_strlen($value)>10000)throw new InvalidArgumentException('A text field is too long.');$data['text'][$i]=$value;}
   foreach((new DOMXPath($doc))->query('//main//img[not(ancestor::*[contains(@class,"material-card")]) and not(ancestor::*[@id="catalogue"])]') as $i=>$n){$id=(string)($_POST['images'][$i]??'');imageUrl($id);$data['images'][$i]=$id;$data['alts'][$i]=mb_substr((string)($_POST['alts'][$i]??$n->getAttribute('alt')),0,300);}
   save('page-'.$slug,'pages',$data);
  }elseif(in_array($section,['products','certificates'],true)){
   $id=(string)($_POST['id']??'');$existing=$id?record($id):[];
   if($id && !query('SELECT id FROM records WHERE id=? AND kind=?',[$id,$section])->fetchColumn())throw new InvalidArgumentException('Item not found.');
   if($action==='delete'){if(($_POST['confirm']??'')!=='yes')throw new InvalidArgumentException('Tick the confirmation box to delete.');query('DELETE FROM records WHERE id=? AND kind=?',[$id,$section]);}
   else{
    $data=['title'=>required('title',150),'description'=>required('description',5000),'published'=>isset($_POST['published'])?'1':'0','order'=>(string)max(0,min(9999,(int)($_POST['order']??0)))];
    if($section==='products'){$data['image']=(string)($_POST['image']??'');imageUrl($data['image']);}
    else{$data['media']=(string)($_POST['media']??'');if($data['media'] && (record($data['media'])['mime']??'')!=='application/pdf')throw new InvalidArgumentException('Choose a PDF from the media library.');}
    save($id?:uid(),$section,$data);
   }
  }elseif($section==='media'){
   if(!upload('file'))throw new InvalidArgumentException('Choose a file to upload.');
  }elseif($section==='enquiries'){
   $id=required('id');if(!query('SELECT id FROM records WHERE id=? AND kind=?',[$id,'enquiries'])->fetchColumn())throw new InvalidArgumentException('Enquiry not found.');
   if($action==='delete'){if(($_POST['confirm']??'')!=='yes')throw new InvalidArgumentException('Tick the confirmation box to delete.');query('DELETE FROM records WHERE id=?',[$id]);}
   else{$data=record($id);$status=required('status');if(!in_array($status,['New','Contacted','Closed'],true))throw new InvalidArgumentException('Invalid status.');$data['status']=$status;$data['notes']=mb_substr((string)($_POST['notes']??''),0,5000);save($id,'enquiries',$data);}
  }elseif($section==='account'){
   if(!password_verify((string)($_POST['current_password']??''),$current['password']))throw new InvalidArgumentException('Current password is incorrect.');
   if(($_POST['password']??'')!==($_POST['password_confirmation']??''))throw new InvalidArgumentException('New passwords do not match.');
   $hash=password((string)($_POST['password']??''));query('UPDATE users SET password=? WHERE id=?',[$hash,$current['id']]);$_SESSION['auth_hash']=$hash;session_regenerate_id(true);
  }elseif($section==='users'){
   if($action==='disable'){$id=required('id');if($id===$current['id'])throw new InvalidArgumentException('You cannot disable your own account.');query('UPDATE users SET active=0 WHERE id=?',[$id]);}
   else{$mail=email(required('email',190));if(query('SELECT id FROM users WHERE email=?',[$mail])->fetchColumn())throw new InvalidArgumentException('That email is already registered.');query('INSERT INTO users(id,email,name,password,active) VALUES(?,?,?,?,1)',[uid(),$mail,required('name',120),password((string)($_POST['password']??''))]);}
  }else throw new InvalidArgumentException('Unknown action.');
  audit('Updated '.$section);$_SESSION['notice']='Changes saved successfully.';
  redirect('/admin/'.$section.($section==='pages'?'?page='.rawurlencode($_POST['slug']):''));
 }catch(InvalidArgumentException $ex){$error=$ex->getMessage();http_response_code(422);}
}
function field(string $key,string $label,array $data=[],string $type='text',bool $required=true): void{
 $value=$_POST[$key]??$data[$key]??'';echo '<label for="f-'.e($key).'">'.e($label).'</label>';
 if($type==='textarea')echo '<textarea id="f-'.e($key).'" name="'.e($key).'" rows="4" '.($required?'required':'').'>'.e($value).'</textarea>';
 else echo '<input id="f-'.e($key).'" name="'.e($key).'" type="'.e($type).'" value="'.($type==='password'?'':e($value)).'" '.($required?'required':'').' '.($type==='password'?'minlength="12" maxlength="72" autocomplete="new-password"':'').'>';
}
function mediaSelect(string $key,string $label,string $selected='',bool $pdf=false): void{
 echo '<label>'.e($label).'<select name="'.e($key).'"><option value="">'.($pdf?'No document uploaded':'Use original / no image').'</option>';
 foreach(records('media') as $r)if($pdf?($r['mime']==='application/pdf'):str_starts_with($r['mime'],'image/'))echo '<option value="'.e($r['id']).'" '.($r['id']===$selected?'selected':'').'>'.e($r['name']).'</option>';
 echo '</select></label>';
}
function formStart(): void {echo '<form method="post">'.csrfField();}
function saveButton(): void {echo '<div class="form-actions"><button type="submit">Save changes</button><span>Changes appear on the public website immediately.</span></div></form>';}
